package storage
import("testing";"strings";"errors";"encoding/json")
func maintenanceFixture(t *testing.T)*Registry{t.Helper();_,r,_:=snapshotFixture(t);if e:=r.ConfigureBackups(ctx,"synthetic-key-1");e!=nil{t.Fatal(e)};return r}
func maintenanceCreate(t *testing.T,r *Registry,generation int64) MaintenanceJob{t.Helper();j,e:=r.QueueMaintenance(ctx,"mutation-run","owner",id(),MaintenanceRequest{Action:"backup.create",Label:"test"});if e!=nil{t.Fatal(e)};if e=r.Transition(ctx,j.OperationID,"queued","running");e!=nil{t.Fatal(e)};if e=r.Transition(ctx,j.OperationID,"running","verifying");e!=nil{t.Fatal(e)};if e=r.RegisterBackup(ctx,j,"/synthetic/"+j.BackupID,strings.Repeat("a",64),123,generation,strings.Repeat("b",64));e!=nil{t.Fatal(e)};return j}
func TestMaintenanceReplayAdmissionCancel(t *testing.T){r:=maintenanceFixture(t);q:=MaintenanceRequest{Action:"backup.create"};key:=id();j,e:=r.QueueMaintenance(ctx,"mutation-run","owner",key,q);if e!=nil{t.Fatal(e)};again,e:=r.QueueMaintenance(ctx,"mutation-run","owner",key,q);if e!=nil||again.OperationID!=j.OperationID{t.Fatal("replay",e)};q.Label="changed";if _,e=r.QueueMaintenance(ctx,"mutation-run","owner",key,q);!errors.Is(e,ErrIdempotencyConflict){t.Fatal(e)};q.Label="";if _,e=r.QueueMaintenance(ctx,"mutation-run","owner",id(),q);!errors.Is(e,ErrOperationInProgress){t.Fatal(e)};if e=r.CancelMaintenance(ctx,"stranger",j.OperationID);!errors.Is(e,ErrJournalConflict){t.Fatal(e)};if e=r.CancelMaintenance(ctx,"owner",j.OperationID);e!=nil{t.Fatal(e)};if _,e=r.QueueMaintenance(ctx,"mutation-run","owner",key,q);e!=nil{t.Fatal("cancelled replay",e)}}
func TestMaintenanceRegisterAndAttestation(t *testing.T){r:=maintenanceFixture(t);j:=maintenanceCreate(t,r,1);path:="/synthetic/"+j.BackupID;sha:=strings.Repeat("a",64);manifest:=strings.Repeat("b",64);if e:=r.RegisterBackup(ctx,j,path,sha,123,1,manifest);e!=nil{t.Fatal(e)};if e:=r.RegisterBackup(ctx,j,path,sha,124,1,manifest);!errors.Is(e,ErrJournalConflict){t.Fatal(e)};b,e:=r.BackupInfo(ctx,j.BackupID);if e!=nil||b.Status!="created"||b.VerifiedAt!=""||b.EncryptedPath!=""{t.Fatal(b,e)};raw,_:=json.Marshal(b);if strings.Contains(string(raw),"synthetic/"){t.Fatal("path exposed")};v,e:=r.QueueMaintenance(ctx,"mutation-run","owner",id(),MaintenanceRequest{Action:"backup.verify",BackupID:j.BackupID,ExpectedHash:sha});if e!=nil{t.Fatal(e)};if e=r.Transition(ctx,v.OperationID,"queued","running");e!=nil{t.Fatal(e)};if e=r.StartMaintenanceVerify(ctx,v);e!=nil{t.Fatal(e)};report:=VerificationReport{BackupID:j.BackupID,Outcome:"verified",CipherSHA256:sha,KeyID:j.KeyID,VerifierRevision:"abcdef1",Checks:VerificationChecks{true,true,true,true,true,true}};bad:=report;bad.KeyID="other";if e=r.CompleteBackupVerify(ctx,"owner",v.OperationID,bad);!errors.Is(e,ErrJournalConflict){t.Fatal(e)};if e=r.CompleteBackupVerify(ctx,"stranger",v.OperationID,report);!errors.Is(e,ErrJournalConflict){t.Fatal(e)};bad=report;bad.Checks.Manifest=false;if e=r.CompleteBackupVerify(ctx,"owner",v.OperationID,bad);!errors.Is(e,ErrInvalidMetadata){t.Fatal(e)};if e=r.CompleteBackupVerify(ctx,"owner",v.OperationID,report);e!=nil{t.Fatal(e)};if e=r.CompleteBackupVerify(ctx,"owner",v.OperationID,report);e!=nil{t.Fatal(e)};if e=r.CancelMaintenance(ctx,"owner",v.OperationID);!errors.Is(e,ErrJournalConflict){t.Fatal("late cancel",e)};bad=report;bad.Outcome="invalid";if e=r.CompleteBackupVerify(ctx,"owner",v.OperationID,bad);!errors.Is(e,ErrJournalConflict){t.Fatal(e)};b,e=r.BackupInfo(ctx,j.BackupID);if e!=nil||b.Status!="verified"||b.VerifiedAt==""{t.Fatal(b,e)}}
func TestMaintenanceUnavailableAndRetention(t *testing.T){r:=maintenanceFixture(t);jobs:=[]MaintenanceJob{};for _,g:=range []int64{1,2,2,2}{j:=maintenanceCreate(t,r,g);jobs=append(jobs,j);if _,e:=r.db.Exec(`UPDATE backups SET status='verified',verified_at='now' WHERE id=?`,j.BackupID);e!=nil{t.Fatal(e)}};p,e:=r.PrunePlan(ctx,2);if e!=nil||len(p.IDs)!=2||!hashPattern.MatchString(p.ExpectedStateHash){t.Fatal(p,e)};for _,bid:=range p.IDs{if bid==jobs[0].BackupID{t.Fatal("last distinct verified generation pruned")}};j:=jobs[3];v,e:=r.QueueMaintenance(ctx,"mutation-run","owner",id(),MaintenanceRequest{Action:"backup.verify",BackupID:j.BackupID,ExpectedHash:strings.Repeat("a",64)});if e!=nil{t.Fatal(e)};_ = r.Transition(ctx,v.OperationID,"queued","running");if e=r.StartMaintenanceVerify(ctx,v);e!=nil{t.Fatal(e)};report:=VerificationReport{BackupID:j.BackupID,Outcome:"unavailable",CipherSHA256:strings.Repeat("a",64),KeyID:j.KeyID,VerifierRevision:"abcdef1"};if e=r.CompleteBackupVerify(ctx,"owner",v.OperationID,report);e!=nil{t.Fatal(e)};b,e:=r.BackupInfo(ctx,j.BackupID);if e!=nil||b.Status!="verified"{t.Fatal(b,e)};if _,e=r.db.Exec(`UPDATE backups SET source_generation=1`);e!=nil{t.Fatal(e)};p,e=r.PrunePlan(ctx,2);if e!=nil||len(p.IDs)!=0{t.Fatal(p,e)}}
